{"function":"async () => {
// list tabbable order approximation via sequential focus is not possible in JS; gather focusable elements incl. shadow
const res=[];
const walk=(root)=>{ root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) walk(e.shadowRoot); if(e.tabIndex>=0 && !e.disabled && e.getClientRects().length && getComputedStyle(e).visibility!=='hidden'){ res.push((e.tagName+'#'+e.id+'.'+(e.className||'')).slice(0,60)+' | '+(e.getAttribute('aria-label')??'')+' | '+e.textContent.trim().slice(0,30)+' | ti='+e.tabIndex);} }); };
walk(document);
return res.slice(0,40);
}"}

